export function getBreedingSitesForWard(wardKey: string, status?: 'open' | 'resolved'): BreedingSite[] {
  return MOCK_BREEDING_SITES.filter(s => {
    if (s.ward_key !== wardKey) return false;
    if (status && s.status !== status) return false;
    return true;
  });
}

export function getBreedingAggregation(wardKey: string): BreedingAggregation | null {
  return BREEDING_AGG_BY_WARD[wardKey] ?? null;
}
